```python
import math

def sieve_of_eratosthenes(n):
    primes = []
    is_prime = [True] * (n + 1)

    # Initialize the list with all entries set as True.
    for i in range(2, int(math.sqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i*i, n+1, i):
                is_prime[j] = False

    # Extract the prime numbers from the list.
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)

    return primes

